var LEGAL={"terms": {"en": {"title": "Terms of Use", "updated": "Last updated: 30 October 2026", "intro": "These terms govern your use of the English Gate website. By using the site, you agree to them. We have kept them short and plain.", "sections": [{"h": "Who we are", "p": "English Gate is an English academy in Baghdad for kids, teens and adults, with online courses for learners anywhere. This website introduces our programmes, our director and the ways to reach us."}, {"h": "No accounts and no forms", "p": "This site has no user accounts and no forms. You can browse all of it without telling us anything. The message builder only prepares a WhatsApp message on your own device; nothing is sent to us unless you choose to send that message yourself."}, {"h": "Registration and payment", "p": "Registration happens through WhatsApp or by phone, or in person at our main centre in Adhamiya. This website does not take registrations or payments."}, {"h": "Content and branding", "p": "The text, logo, character, design, photos and videos on this site belong to English Gate. Photos and videos of students appear with their families’ consent. Please do not copy or reuse any of it without permission."}, {"h": "External links", "p": "Links to WhatsApp, Telegram, Instagram, TikTok, Facebook, YouTube, LinkedIn and Google Maps open third-party platforms that work under their own terms; we do not control them."}, {"h": "Changes", "p": "We may update these terms from time to time; the date above always shows the current version."}], "contact": "Questions about these terms? Message us on WhatsApp."}, "ar": {"title": "شروط الاستخدام", "updated": "آخر تحديث: ٣٠ تشرين الأول ٢٠٢٦", "intro": "تنظّم هذه الشروط استخدامكم لموقع انكلش كيت، وباستخدام الموقع فأنتم توافقون عليها. كتبناها قصيرة وواضحة.", "sections": [{"h": "من نحن", "p": "انكلش كيت أكاديمية لتعليم اللغة الانكليزية في بغداد للأطفال واليافعين والكبار، مع كورسات أونلاين للمتعلمين في أي مكان. يعرّف هذا الموقع ببرامجنا ومديرتنا وطرق التواصل معنا."}, {"h": "لا حسابات ولا استمارات", "p": "لا يحتوي هذا الموقع على حسابات مستخدمين ولا على استمارات، ويمكنكم تصفّحه كاملاً دون أن تخبرونا بأي شيء. أداة كتابة الرسالة تجهّز رسالة واتساب على جهازكم فقط، ولا يصلنا شيء ما لم ترسلوا الرسالة بأنفسكم."}, {"h": "التسجيل والدفع", "p": "يتم التسجيل عبر واتساب أو الهاتف، أو حضورياً في مركزنا الرئيسي في الأعظمية. لا يستقبل هذا الموقع تسجيلات ولا مدفوعات."}, {"h": "المحتوى والعلامة", "p": "النصوص والشعار والشخصية والتصميم والصور والفيديوهات في هذا الموقع ملك لانكلش كيت. تظهر صور الطلاب وفيديوهاتهم بموافقة عوائلهم. يرجى عدم نسخ أي منها أو إعادة استخدامه دون إذن."}, {"h": "الروابط الخارجية", "p": "روابط واتساب وتيليگرام وانستغرام وتيك توك وفيسبوك ويوتيوب ولينكدإن وخرائط كوكل تفتح منصات خارجية تعمل وفق شروطها الخاصة، ولا نتحكم بها."}, {"h": "التعديلات", "p": "قد نحدّث هذه الشروط من وقت لآخر، والتاريخ أعلاه يبيّن النسخة الحالية دائماً."}], "contact": "عندكم سؤال عن هذه الشروط؟ راسلونا على واتساب."}}, "privacy": {"en": {"title": "Privacy Policy", "updated": "Last updated: 30 October 2026", "intro": "We work with children and their families, so we keep privacy simple and serious: this website has no accounts, no forms, no cookies and no analytics. Here is exactly what happens.", "sections": [{"h": "What the site stores on your device", "p": "One small local value: your language choice (Arabic or English), kept in your browser’s localStorage. It stays on your device and is never sent to us or anyone else."}, {"h": "What you share when you contact us", "p": "The message builder prepares a WhatsApp message on your device; nothing is sent until you send it yourself in WhatsApp. If you message or call us, you share your name and phone number so we can reply, and we use them only for that."}, {"h": "No analytics, no tracking", "p": "This site loads no analytics or tracking scripts and sets no cookies."}, {"h": "Videos, fonts and the 3D street", "p": "Videos and fonts are served from our own website, and the 3D street is drawn on your own device. No video platform is embedded, so watching involves no third-party video tracking."}, {"h": "Maps and other platforms", "p": "There is no embedded map. The Google Maps link, and the links to our social accounts, open those platforms, which handle your data under their own policies."}, {"h": "Children’s privacy", "p": "This website does not collect personal information from anyone, children included. All communication about a child runs with their parent or guardian."}, {"h": "Your choices", "p": "You can clear the stored language value from your browser settings at any time, and you can always message us about anything you have shared with us."}], "contact": "Privacy questions? Message us on WhatsApp and we will help."}, "ar": {"title": "سياسة الخصوصية", "updated": "آخر تحديث: ٣٠ تشرين الأول ٢٠٢٦", "intro": "نعمل مع الأطفال وعوائلهم، لذلك نتعامل مع الخصوصية ببساطة وجدّية: هذا الموقع بلا حسابات، بلا استمارات، بلا ملفات تعريف ارتباط وبلا أدوات تحليل. وهذا بالضبط ما يحدث.", "sections": [{"h": "ما يحفظه الموقع على جهازكم", "p": "قيمة محلية صغيرة واحدة: اختياركم للغة (العربية أو الانكليزية)، محفوظة في localStorage في متصفحكم. تبقى على جهازكم ولا تُرسل إلينا ولا إلى أي جهة."}, {"h": "ما تشاركونه عند التواصل معنا", "p": "أداة كتابة الرسالة تجهّز رسالة واتساب على جهازكم، ولا يُرسل شيء حتى ترسلوها أنتم من واتساب. إذا راسلتمونا أو اتصلتم بنا فإنكم تشاركون اسمكم ورقمكم حتى نرد عليكم، ونستخدمهما لهذا فقط."}, {"h": "لا تحليلات ولا تتبّع", "p": "لا يحمّل هذا الموقع أي أدوات تحليل أو تتبّع، ولا يضع ملفات تعريف ارتباط."}, {"h": "الفيديوهات والخطوط والشارع ثلاثي الأبعاد", "p": "الفيديوهات والخطوط تُقدَّم من موقعنا نفسه، والشارع ثلاثي الأبعاد يُرسم على جهازكم. لا توجد منصة فيديو مضمّنة، لذلك لا يوجد تتبّع من طرف ثالث عند المشاهدة."}, {"h": "الخرائط والمنصات الأخرى", "p": "لا توجد خريطة مضمّنة. رابط خرائط كوكل وروابط حساباتنا تفتح تلك المنصات، وهي تتعامل مع بياناتكم وفق سياساتها الخاصة."}, {"h": "خصوصية الأطفال", "p": "لا يجمع هذا الموقع معلومات شخصية من أي أحد، والأطفال من ضمنهم. كل تواصل يخص الطفل يتم مع وليّ أمره."}, {"h": "خياراتكم", "p": "يمكنكم مسح قيمة اللغة المحفوظة من إعدادات المتصفح في أي وقت، ويمكنكم دائماً مراسلتنا بخصوص أي شيء شاركتموه معنا."}], "contact": "عندكم سؤال عن الخصوصية؟ راسلونا على واتساب ونساعدكم."}}, "cookies": {"en": {"title": "Cookie Policy", "updated": "Last updated: 30 October 2026", "intro": "The short version: this website sets no cookies.", "sections": [{"h": "No cookies from us", "p": "The site uses no cookies at all, and loads no analytics."}, {"h": "What we use instead", "p": "One local browser value: your language preference, in localStorage. It never leaves your device, and you can clear it from your browser settings anytime."}, {"h": "Third-party platforms you open", "p": "If you open WhatsApp, Telegram, our social accounts or Google Maps from our links, those platforms may set their own cookies on their own sites, under their own policies."}, {"h": "Managing storage", "p": "Your browser settings let you view, limit and delete cookies and local storage at any time."}], "contact": "Questions about cookies? Message us on WhatsApp."}, "ar": {"title": "سياسة ملفات تعريف الارتباط", "updated": "آخر تحديث: ٣٠ تشرين الأول ٢٠٢٦", "intro": "باختصار: هذا الموقع لا يضع أي ملفات تعريف ارتباط.", "sections": [{"h": "لا ملفات تعريف ارتباط منّا", "p": "لا يستخدم الموقع أي ملفات تعريف ارتباط، ولا يحمّل أدوات تحليل."}, {"h": "ما نستخدمه بدلاً منها", "p": "قيمة محلية واحدة في المتصفح: تفضيل اللغة، في localStorage. لا تغادر جهازكم، ويمكنكم مسحها من إعدادات المتصفح في أي وقت."}, {"h": "المنصات الخارجية التي تفتحونها", "p": "إذا فتحتم واتساب أو تيليگرام أو حساباتنا أو خرائط كوكل من روابطنا، فقد تضع تلك المنصات ملفاتها الخاصة على مواقعها، وفق سياساتها."}, {"h": "إدارة التخزين", "p": "تتيح لكم إعدادات المتصفح عرض ملفات تعريف الارتباط والتخزين المحلي وتقييدها وحذفها في أي وقت."}], "contact": "عندكم سؤال عن ملفات تعريف الارتباط؟ راسلونا على واتساب."}}};
