/* ===================== English Gate preview, v4: behaviour ===================== */
var root=document.documentElement,lang='ar';
var reduceMQ=window.matchMedia('(prefers-reduced-motion: reduce)');
var HOOKS=[];
function $$(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s));}
function clamp(x){return x<0?0:x>1?1:x;}
function tr(en,ar){return lang==='ar'?ar:en;}
function T(o){return o?(lang==='ar'?o.ar:o.en):'';}
function escH(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function icon(id,cls){return '<svg class="'+(cls||'i')+'" aria-hidden="true"><use href="#'+id+'"/></svg>';}
function el(tag,cls,html){var e=document.createElement(tag);if(cls)e.className=cls;if(html!=null)e.innerHTML=html;return e;}
function waHref(msg){return 'https://wa.me/'+PHONE+'?text='+encodeURIComponent(msg);}
function en(s){return '<span class="en" lang="en" dir="ltr" data-lang-exempt>'+escH(s)+'</span>';}
function isRTL(){return root.dir==='rtl';}
function digits(s){if(lang!=='ar')return String(s);return String(s).replace(/[0-9]/g,function(d){return '٠١٢٣٤٥٦٧٨٩'[+d];});}
function smooth(){return reduceMQ.matches?'auto':'smooth';}

/* ---------- the opening hands the page over when it is done (or at once, when it does not play) ---------- */
var INTRO={on:root.classList.contains('intro-on'),done:false,cbs:[]};
function whenIntroDone(fn){if(!INTRO.on||INTRO.done)fn(false);else INTRO.cbs.push(fn);}

/* ---------- language ---------- */
var langBtn=document.getElementById('langBtn');
function apply(l){
  lang=l;var ar=l==='ar';root.lang=l;root.dir=ar?'rtl':'ltr';
  document.title=ar?'أكاديمية انكلش كيت':'English Gate Academy';
  $$('[data-en]').forEach(function(e){var t=e.getAttribute('data-'+l);if(t!==null)e.textContent=t;});
  $$('[data-en-html]').forEach(function(e){var t=e.getAttribute('data-'+l+'-html');if(t!==null)e.innerHTML=t;});
  $$('[data-aria-en]').forEach(function(e){e.setAttribute('aria-label',e.getAttribute('data-aria-'+l));});
  $$('[data-alt-en]').forEach(function(e){e.alt=e.getAttribute('data-alt-'+l);});
  $$('[data-srcset-en]').forEach(function(e){var v=e.getAttribute('data-srcset-'+l);if(e.getAttribute('srcset')!==v)e.setAttribute('srcset',v);});
  $$('[data-src-en]').forEach(function(e){var v=e.getAttribute('data-src-'+l);if(e.getAttribute('src')!==v)e.setAttribute('src',v);});
  $$('[data-wa]').forEach(function(e){e.href=waHref(MSG[e.getAttribute('data-wa')]||MSG.general);});
  langBtn.textContent=ar?'English':'العربية';langBtn.lang=ar?'en':'ar';langBtn.setAttribute('aria-label',ar?'Switch to English':'التبديل إلى العربية');
  document.getElementById('burger').setAttribute('aria-label',ar?'القائمة':'Menu');
  HOOKS.forEach(function(fn){try{fn(l);}catch(e){if(window.console)console.error(e);}});
  try{localStorage.setItem('eg_lang',l);}catch(e){}
}
langBtn.addEventListener('click',function(){apply(lang==='ar'?'en':'ar');});

/* ---------- dates in Baghdad: what is still upcoming, and how far away ---------- */
function baghdadToday(){try{return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Baghdad',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
  catch(e){var d=new Date();return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2);}}
function daysUntil(iso){var a=baghdadToday().split('-').map(Number),b=iso.split('-').map(Number);return Math.round((Date.UTC(b[0],b[1]-1,b[2])-Date.UTC(a[0],a[1]-1,a[2]))/864e5);}
function pastDate(iso){return daysUntil(iso)<0;}
function inDays(n){if(n===0)return tr('Today','اليوم');if(n===1)return tr('Tomorrow','باچر');
  if(lang==='ar'){if(n===2)return 'باقي يومين';return 'باقي '+digits(n)+(n<=10?' أيام':' يوم');}return 'In '+n+' days';}
(function(){
  $$('[data-until]').forEach(function(e){if(pastDate(e.getAttribute('data-until')))e.hidden=true;});
  var c=document.getElementById('wsCount'),p=document.getElementById('wsPoster');
  function count(){if(!c||!p||p.hidden)return;c.textContent=inDays(daysUntil(p.getAttribute('data-until')));}
  HOOKS.push(count);
})();

