/* ---------- the closing builder writes the Arabic message ---------- */
(function(){
  var B=document.getElementById('builder');if(!B)return;
  var bubble=document.getElementById('bubble'),gloss=document.getElementById('gloss'),send=document.getElementById('bSend'),copyB=document.getElementById('bCopy'),clearB=document.getElementById('bClear'),chips=$$('.tchip',B),last='';
  function pressed(g){return chips.filter(function(c){return c.getAttribute('data-g')===g&&c.getAttribute('aria-pressed')==='true';});}
  function list(a,and){return a.length<2?a.join(''):a.slice(0,-1).join(', ')+and+a[a.length-1];}
  /* the message itself is always Arabic (repo S44); in English mode a plain gloss sits under it */
  function compose(){
    var what=pressed('what'),who=pressed('who')[0],where=pressed('where')[0];
    var s='السلام عليكم،',g='Hello,';
    if(what.length){s+=' أريد الاستفسار عن '+what.map(function(c){return c.getAttribute('data-msg');}).join(' و')+(who?' '+who.getAttribute('data-msg'):'')+'.';
      g+=' I would like to ask about '+list(what.map(function(c){return c.getAttribute('data-gloss');}),' and ')+(who?' '+who.getAttribute('data-gloss'):'')+'.';}
    else if(who){s+=' أريد الاستفسار عن الكورسات المناسبة '+who.getAttribute('data-msg')+'.';g+=' I would like to ask about the right courses '+who.getAttribute('data-gloss')+'.';}
    else{s+=' أريد الاستفسار عن كورسات انكلش كيت.';g+=' I would like to ask about English Gate courses.';}
    if(where){s+='\nالحضور: '+where.getAttribute('data-msg')+'.';g+=' Attending '+where.getAttribute('data-gloss')+'.';}
    return {ar:s,en:g};
  }
  function update(pulse){var m=compose();last=m.ar;bubble.textContent=m.ar;var d=new Date();bubble.appendChild(el('span','meta',digits(('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2))));send.href=waHref(m.ar);
    gloss.hidden=lang==='ar';gloss.textContent=lang==='ar'?'':'In English: '+m.en;
    if(pulse&&!reduceMQ.matches){bubble.classList.remove('pulse');void bubble.offsetWidth;bubble.classList.add('pulse');}}
  HOOKS.push(function(){update(false);});
  chips.forEach(function(c){c.addEventListener('click',function(){var g=c.getAttribute('data-g'),on=c.getAttribute('aria-pressed')==='true';
    if(g==='what')c.setAttribute('aria-pressed',on?'false':'true');else{chips.forEach(function(o){if(o.getAttribute('data-g')===g)o.setAttribute('aria-pressed','false');});if(!on)c.setAttribute('aria-pressed','true');}update(true);});});
  copyB.addEventListener('click',function(){var lab=copyB.querySelector('span');function ok(){copyB.classList.add('done');lab.textContent=tr('Copied','انسخت');setTimeout(function(){copyB.classList.remove('done');lab.textContent=tr('Copy','نسخ');},1500);}
    if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(last).then(ok,function(){});});
  clearB.addEventListener('click',function(){chips.forEach(function(c){c.setAttribute('aria-pressed','false');});update(true);});
})();


