/* ---------- pages over the site: her page and the legal pages. Opened by #rusul / #privacy / #terms / #cookies here,
   and by the real paths /rusul, /privacy, /terms, /cookies on the live site (every path serves this one page) ---------- */
(function(){
  var rp=document.getElementById('rp'),lg=document.getElementById('lg');if(!rp||!lg)return;
  var PAGES={rusul:rp,privacy:lg,terms:lg,cookies:lg},SECT={programs:'courses',placement:'placement',workshop:'workshops',moments:'watch',videos:'watch',faq:'faq',contact:'contact',about:'management',testimonials:'watch',staff:null,careers:null};
  var openEl=null,lastY=0,legalKey='privacy';
  function pathKey(){return location.pathname.replace(/\/+$/,'').split('/').pop().toLowerCase();}
  function wanted(){var h=location.hash.slice(1).toLowerCase();if(PAGES[h])return h;var p=pathKey();if(p==='staff')return 'rusul';return PAGES[p]?p:null;}
  function fillLegal(k){legalKey=k;var d=LEGAL[k][lang==='ar'?'ar':'en'];
    document.getElementById('lgTitle').textContent=d.title;document.getElementById('lgUpd').textContent=d.updated;document.getElementById('lgIntro').textContent=d.intro;
    document.getElementById('lgSecs').innerHTML=d.sections.map(function(x){return '<section><h2>'+escH(x.h)+'</h2><p>'+escH(x.p)+'</p></section>';}).join('');
    document.getElementById('lgContact').textContent=d.contact;
    $$('[data-lg]',lg).forEach(function(a){a.setAttribute('aria-current',a.getAttribute('data-lg')===k?'page':'false');});}
  function show(k){var el=PAGES[k];if(el===lg)fillLegal(k);
    if(openEl===el){el.scrollTop=0;return;}
    if(openEl)hide(false,true);
    lastY=window.scrollY;openEl=el;el.hidden=false;root.classList.add('rp-on');el.scrollTop=0;
    requestAnimationFrame(function(){el.classList.add('in');});var b=el.querySelector('.rp-back');try{b.focus({preventScroll:true});}catch(e){}}
  function hide(toId,keep){if(!openEl)return;var el=openEl;openEl=null;el.classList.remove('in');el.hidden=true;if(!keep)root.classList.remove('rp-on');
    if(keep)return;if(toId){var m=document.getElementById(toId);if(m)m.scrollIntoView();}else window.scrollTo(0,lastY);}
  function route(){var k=wanted();if(k)show(k);else hide(false);}
  function leave(toId){var p=pathKey(),base=PAGES[p]||p==='staff'?'/':location.pathname+location.search;
    try{history.replaceState(null,'',base+(toId?'#'+toId:''));}catch(x){}hide(toId);}
  window.addEventListener('hashchange',route);
  document.getElementById('rpBack').addEventListener('click',function(e){e.preventDefault();leave('management');});
  document.getElementById('lgBack').addEventListener('click',function(e){e.preventDefault();leave(null);});
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&openEl&&!document.querySelector('dialog[open]'))leave(openEl===rp?'management':null);});
  HOOKS.push(function(){if(openEl===lg)fillLegal(legalKey);});
  route();
  /* on the live site every route has its own title and canonical address */
  var TITLES={'':['انكلش كيت English Gate | أكاديمية الانكليزي ببغداد وأونلاين','English Gate | English academy in Baghdad and online'],
    programs:['كل كورسات وبرامج انكلش كيت','All English Gate courses and programmes'],rusul:['رسل ثائر، مديرة أكاديمية انكلش كيت','Rusul Thaer, Academy Director of English Gate'],
    placement:['اختبار تحديد المستوى | انكلش كيت','The placement test | English Gate'],workshop:['الورش الشهرية | انكلش كيت','Monthly workshops | English Gate'],
    moments:['فيديوهات من انكلش كيت','Videos from English Gate'],faq:['أسئلة وأجوبة عن انكلش كيت','Questions about English Gate'],
    contact:['تواصل ويا انكلش كيت','Contact English Gate'],about:['عن انكلش كيت','About English Gate'],
    privacy:['سياسة الخصوصية | انكلش كيت','Privacy Policy | English Gate'],terms:['شروط الاستخدام | انكلش كيت','Terms of Use | English Gate'],cookies:['سياسة ملفات الارتباط | انكلش كيت','Cookie Policy | English Gate']};
  function stamp(){var c=document.querySelector('link[rel=canonical]');if(!c)return;   /* only the site build has a canonical link */
    var p=pathKey();if(p==='staff')p='rusul';var t=TITLES[p]||TITLES[''];document.title=t[lang==='ar'?0:1];c.href='https://englishgate-school.com/'+(TITLES[p]?p:'');}
  stamp();HOOKS.push(stamp);
  /* the live site's section paths (/programs, /faq, ...) land on their section */
  /* the page settles for a moment after load (pictures, the street), so the landing repeats until then, unless the visitor moves first */
  var sk=pathKey();if(!wanted()&&SECT[sk]){var moved=false,go=function(){if(moved)return;var el=document.getElementById(SECT[sk]);if(el)el.scrollIntoView({behavior:'instant',block:'start'});};
    ['wheel','touchstart','keydown','pointerdown'].forEach(function(t){window.addEventListener(t,function(){moved=true;},{once:true,passive:true});});
    var land=function(){[60,400,1000,2000].forEach(function(ms){setTimeout(go,ms);});};
    if(document.readyState==='complete')land();else window.addEventListener('load',land);}
})();

/* ---------- gates through the page: every section title opens like the gate, each promise waits behind a small gate,
   and the footer shows the gate again, ajar. All of it opens once, as it arrives; with reduced motion or no observer
   nothing is held closed (the CSS only closes them under html.gr-on). ---------- */
(function(){
  var titles=$$('.section .h2').filter(function(h){return !h.closest('.hero');}),prs=$$('.pr'),fg=document.getElementById('footGate');
  if(reduceMQ.matches||!('IntersectionObserver' in window)){prs.concat(fg?[fg]:[]).forEach(function(n){n.classList.add('open');});return;}
  titles.forEach(function(h){h.classList.add('gr');});
  root.classList.add('gr-on');
  var io=new IntersectionObserver(function(es){es.forEach(function(e){if(!e.isIntersecting)return;e.target.classList.add('open');io.unobserve(e.target);});},{rootMargin:'0px 0px -12% 0px'});
  titles.concat(prs).concat(fg?[fg]:[]).forEach(function(n){io.observe(n);});
})();
/* ---------- from the street into the page: past the hero the night goes on for a moment, and the page opens through
   a lit arch that widens as it comes up the screen ---------- */
(function(){
  var sec=document.getElementById('moments');if(!sec||reduceMQ.matches)return;
  var NS='http://www.w3.org/2000/svg',svg=document.createElementNS(NS,'svg');svg.setAttribute('class','mo-gate');svg.setAttribute('aria-hidden','true');
  var dark=document.createElementNS(NS,'path'),glow=document.createElementNS(NS,'path'),rim=document.createElementNS(NS,'path');
  dark.setAttribute('class','g-dark');dark.setAttribute('fill-rule','evenodd');glow.setAttribute('class','g-glow');rim.setAttribute('class','g-rim');
  svg.appendChild(dark);svg.appendChild(glow);svg.appendChild(rim);sec.insertBefore(svg,sec.firstChild);
  var last=-1,tk=false;
  function draw(){tk=false;
    var r=sec.getBoundingClientRect(),vh=window.innerHeight||800;
    var p=clamp((vh-r.top)/(vh*.78));if(Math.abs(p-last)<.002)return;last=p;
    var W=svg.clientWidth||sec.clientWidth,H=svg.clientHeight||1;svg.setAttribute('viewBox','0 0 '+W+' '+H);
    svg.style.display=p>=1?'none':'';if(p>=1)return;svg.style.opacity=p>.82?((1-p)/.18).toFixed(3):'';
    var e=p*p*(3-2*p),cx=W/2,rx=W*(.15+.62*e),ry=Math.min(H*(.5+1.25*e),H*.985);
    var arch='M'+(cx-rx)+' '+H+' A'+rx+' '+ry+' 0 0 1 '+(cx+rx)+' '+H;
    dark.setAttribute('d','M0 0H'+W+'V'+H+'H0Z '+arch+'Z');glow.setAttribute('d',arch);rim.setAttribute('d',arch);
  }
  function on(){if(!tk){tk=true;requestAnimationFrame(draw);}}
  window.addEventListener('scroll',on,{passive:true});window.addEventListener('resize',function(){last=-1;on();});draw();
})();
/* ---------- moments: on wide screens one doorway stays on screen and each line brings its moment into it ---------- */
(function(){
  var st=document.querySelector('.mo-stage');if(!st)return;
  var imgs=$$('.ms-img',st),ticks=$$('.ms-ticks i',st),rows=$$('.mo'),cur=-1,z=1,t=0;
  function set(i){if(i===cur||!imgs[i])return;var im=imgs[i],down=i>cur;
    im.classList.remove('on');im.classList.toggle('from-top',!down&&cur>-1);im.style.zIndex=++z;void im.offsetWidth;im.classList.add('on');
    cur=i;ticks.forEach(function(x,j){x.classList.toggle('on',j===i);});
    clearTimeout(t);t=setTimeout(function(){imgs.forEach(function(x,j){if(j!==cur)x.classList.remove('on');});},1100);}
  function pick(){if(!st.offsetParent)return;var vh=window.innerHeight||800,best=0,bd=1e9;
    rows.forEach(function(r,i){var b=r.getBoundingClientRect(),d=Math.abs(b.top+b.height/2-vh*.5);if(d<bd){bd=d;best=i;}});set(best);}
  var tk=false;function on(){if(!tk){tk=true;requestAnimationFrame(function(){tk=false;pick();});}}
  window.addEventListener('scroll',on,{passive:true});window.addEventListener('resize',on);
  set(0);pick();
})();
/* ---------- real classrooms: each photo opens from the bottom as it arrives; the columns drift a little ---------- */
(function(){
  var box=document.getElementById('phs');if(!box)return;
  var phs=$$('.ph',box),cols=$$('.ph-col',box);
  if(!reduceMQ.matches&&'IntersectionObserver' in window){
    root.classList.add('ph-on');
    var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});},{rootMargin:'0px 0px -8% 0px'});
    phs.forEach(function(p){io.observe(p);});
  }
  if(reduceMQ.matches)return;
  var SP=[-34,30,-12],tk=false;
  function drift(){tk=false;if(window.innerWidth<700){cols.forEach(function(c){c.style.removeProperty('--drift');});return;}
    var r=box.getBoundingClientRect(),vh=window.innerHeight||800,p=clamp((vh-r.top)/(vh+r.height))-.5;
    cols.forEach(function(c,i){c.style.setProperty('--drift',(p*SP[i]*2).toFixed(1)+'px');});}
  function on(){if(!tk){tk=true;requestAnimationFrame(drift);}}
  window.addEventListener('scroll',on,{passive:true});window.addEventListener('resize',on);drift();
})();

/* ---------- the opening: the shield arrives with the academy's name and its line, From Gate to Great. The two letters
   of the shield are the two leaves of the gate; they swing open on their hinges and the light behind them becomes the hall of doors. On every visit, never for reduced motion, and any
   tap or key skips it (the decision is made before the first paint, so returning visitors never see a flash). ---------- */
(function(){
  var box=document.getElementById('gi');if(!box)return;
  if(!INTRO.on){box.parentNode.removeChild(box);return;}
    var ended=false,hold=!!window.__holdIntro;   /* the preview's frame-by-frame test only */
  box.classList.add('play');
  var t1=hold?0:setTimeout(function(){box.classList.add('open');},2700);   /* the shield is drawn and lit, then the name and the slogan are read */
  var t2=hold?0:setTimeout(function(){out(false);},3650);
  function release(){if(INTRO.done)return;INTRO.done=true;INTRO.cbs.splice(0).forEach(function(fn){try{fn(true);}catch(e){}});}
  function out(fast){if(ended)return;ended=true;clearTimeout(t1);clearTimeout(t2);box.classList.add('out');if(fast)box.classList.add('fast');release();if(!hold)setTimeout(finish,fast?280:540);}
  function finish(){if(box.parentNode)box.parentNode.removeChild(box);root.classList.remove('intro-on');release();}
  box.addEventListener('click',function(){out(true);});
  function key(){out(true);document.removeEventListener('keydown',key);}
  document.addEventListener('keydown',key);
  /* a safety net: the page is never held behind the opening */
  if(!hold)setTimeout(function(){if(box.parentNode)finish();},6500);
  window.__intro={open:function(){box.classList.add('open');},out:out,finish:finish};
})();

